import copy
import hashlib
import json
import os
import sys
import time
from types import SimpleNamespace

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_readout_2c as R2C  # noqa: E402
import p1v4_readout_2d as R2D  # noqa: E402
import p1v4_readout_allclass as AC  # noqa: E402
import p1v4_score as S  # noqa: E402

DB = 10
NAME = f"dev_dnoise{DB}"
R = "data/p1v4/runs"
OUT = f"{R}/noise_pilot/{NAME}"
PARTS = ("r_hear", "s_move")
API_SETTING = {"b2fast": "K48_think_prec", "b2strong": "K48_think_prec", "b3": "A6_nothink"}
API_NAME = {"b2fast": "B2-fast", "b2strong": "B2-strong", "b3": "B3"}


def patch_folders():
    """Let p1v4_data (and so Context and the API script) read the dev variant folder like a split."""
    orig = D.folders

    def folders(which, final=False):
        if isinstance(which, str) and which.startswith("dev_d"):
            return [f"{D.RENDER}/{which}"]
        return orig(which, final)
    D.folders = folders


def clean_rows(units=None):
    rows = [r for r in D.load_rows("dev") if r["part"] in PARTS]
    return [r for r in rows if units is None or r["unit"] in units]


# ------------------------------------------------------------------------------------------------ render

def render():
    import soundfile as sf
    import p1v4_units as U
    out = os.path.join(D.RENDER, NAME)
    os.makedirs(out, exist_ok=True)
    A = U.Assets("dev")
    by = {}
    for r in clean_rows():
        by.setdefault(r["unit"], []).append(r)
    meta, gains, t0 = [], [], time.time()
    for u, rows in sorted(by.items()):
        spec = copy.deepcopy(rows[0]["spec"])
        spec["snr_db"] = round(spec["snr_db"] - DB, 2)
        tls = {r["version"]: SimpleNamespace(src=r["sources"], points=r["points"], assistant=r["assistant"])
               for r in rows}
        audio, gain_db = U.render_versions(spec, tls, A)
        gains.append(gain_db - rows[0]["gain_db"])
        for r in rows:
            nr = copy.deepcopy(r)
            nr["spec"]["snr_db"] = spec["snr_db"]
            nr["gain_db"] = gain_db
            nr["peak"] = round(float(np.abs(audio[r["version"]]).max()) / 32767, 4)
            for p in nr["points"]:
                w = U.windows(audio[r["version"]], [p])[0]
                assert len(w) == int(D.WIN_S * D.SR)
                path = os.path.join(out, f"{u}_{r['version']}_p{p['k']}.wav").replace("\\", "/")
                sf.write(path, w, U.SR, subtype="PCM_16")
                p["window"] = path
                p["sha256"] = hashlib.sha256(open(path, "rb").read()).hexdigest()
            meta.append(nr)
    with open(os.path.join(out, "meta.jsonl"), "w", encoding="utf-8") as f:
        for r in meta:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    g = np.array(gains)
    info = {"units": len(by), "rows": len(meta), "db_louder_noise": DB, "seconds": round(time.time() - t0, 1),
            "gain_change_db": {"units_scaled_down": int((g < -1e-9).sum()), "min": float(g.min()),
                               "median": float(np.median(g))}}
    os.makedirs(OUT, exist_ok=True)
    json.dump(info, open(f"{OUT}/render_info.json", "w"), indent=1)
    print(json.dumps(info))


# ------------------------------------------------------------------------------------------------ local systems

def forward(rows, ctx, model, label):
    import soundfile as sf
    import torch
    wins = D.windows_of(rows, label)
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    items = []
    for w in wins:
        r = rows_by[w["key"]]
        text, asks = ctx.situation(r, w["k"], "full")
        items.append({"id": w["id"], "path": w["path"], "text": text,
                      "marker": "agent" if w["assistant_speaking"] else "user",
                      "qs": [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]})
    H, E, SM, SX, QW, QT, PO = [], [], [], [], [], [], []
    t0 = time.time()
    for i in range(0, len(items), 8):
        chunk = items[i:i + 8]
        waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
        h, e, qs, po = RO.forward_states(model, waves, [it["text"] for it in chunk], [it["marker"] for it in chunk],
                                         [[RO.TASK[q] for q in it["qs"]] for it in chunk])
        sm, sx, _ = R2D.per_second(model.vt, waves)
        H.append(h.astype(np.float16))
        E.append(e.astype(np.float16))
        SM.append(sm.astype(np.float16))
        SX.append(sx.astype(np.float16))
        QW.append(qs + i)
        QT += [q for it in chunk for q in it["qs"]]
        PO.append(po)
    z = {"states": np.concatenate(H), "ears": np.concatenate(E), "q_win": np.concatenate(QW), "q_task": np.array(QT),
         "p_old": np.concatenate(PO), "ids": np.array([it["id"] for it in items]),
         "sec_mean": np.concatenate(SM), "sec_max": np.concatenate(SX)}
    np.savez(f"{OUT}/feats_{label}.npz", **z)
    print(f"{label}: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)
    return z


def b1_decisions(rows, ctx):
    import p1v4_b1 as B1
    lists = json.load(open(f"{R}/b1/mined_phrases.json"))
    best = json.load(open(f"{R}/b1/b1_dev.json"))["setting"]
    grid = B1.Grid()
    target = np.array([B1.GRID[n].index(best[n]) for n in grid.names])
    i = int(np.where((grid.idx == target).all(1))[0][0])
    assert grid.setting(i) == best
    pts = B1.point_inputs(rows, ctx, lists)
    return B1.decisions_for(pts, grid, i)


def local():
    import torch
    import p1v4_l1 as L1
    patch_folders()
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    noisy = [r for r in D.load_rows(NAME)]
    units = {r["unit"] for r in noisy}
    clean = clean_rows(units)
    assert len(clean) == len(noisy)
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    ro = {"2b ears": ("ears", AC.load_allclass()), "2c ears": ("ears", R2C.load_2c()), "2d": ("2d", R2D.load_2d())}
    stored_b1 = {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v
                 for k, v in json.load(open(f"{R}/b1/decisions_dev.json")).items()}
    for label, rows, ctx in (("clean", clean, C.Context("dev")), ("noisy", noisy, C.Context(NAME))):
        z = forward(rows, ctx, model, label)
        sc = {"old head": RO.scores_of(z, None, None)}
        for n, (setting, r) in ro.items():
            sc[n] = R2D.scores_2d(z, R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"]), r) if setting == "2d" \
                else RO.scores_of(z, setting, r)
        json.dump({n: {"|".join(map(str, k)): v for k, v in s.items()} for n, s in sc.items()},
                  open(f"{OUT}/scores_{label}.json", "w"))
        dec = b1_decisions(rows, ctx)
        json.dump({"|".join(map(str, k)): v for k, v in dec.items()}, open(f"{OUT}/b1_{label}.json", "w"))
        if label == "clean":
            diff = sum(dec[k] != stored_b1.get(k) for k in dec)
            print(f"B1-strong on clean dev reproduces the stored decisions: {len(dec) - diff}/{len(dec)}", flush=True)


# ------------------------------------------------------------------------------------------------ API rivals

def call_no_logprobs(key, model, parts, think, tier="standard"):
    """p1v4_api.call without the logprob request (answers only)."""
    import random
    import urllib.error
    import urllib.request
    import p1v4_api as API
    cfg = {"temperature": 0, "maxOutputTokens": API.MAX_OUT}
    if think == "nothink":
        cfg["thinkingConfig"] = {"thinkingBudget": 0}
    body = {"contents": [{"role": "user", "parts": parts}], "generationConfig": cfg}
    data = json.dumps(body).encode("utf-8")
    err = None
    for attempt in range(API.TRIES):
        req = urllib.request.Request(API.URL.format(model), data=data,
                                     headers={"x-goog-api-key": key, "Content-Type": "application/json",
                                              "X-Server-Timeout": str(API.TIMEOUT_S - 60)})
        t0 = time.perf_counter()
        try:
            with urllib.request.urlopen(req, timeout=API.TIMEOUT_S) as resp:
                js = json.loads(resp.read().decode("utf-8"))
                js["_served_tier"] = resp.headers.get("x-gemini-service-tier")
                return 200, js, time.perf_counter() - t0, attempt
        except urllib.error.HTTPError as e:
            err = (e.code, e.read().decode("utf-8", "replace")[:400])
            if e.code not in (429, 500, 502, 503, 504):
                break
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as e:
            err = (-1, repr(e)[:300])
        time.sleep(min(300.0, 2.0 * 2 ** attempt) * (0.5 + random.random()))
    return err[0], {"error": err[1]}, None, attempt


CLEAN = "dev_dclean"


def clean_folder():
    """A dev variant folder with the same R-hear and S-move rows and windows as dev (nothing re-rendered) and the dev
    front-end files under its name, so the clean questions can be re-asked through the same code path as the noisy
    ones (added 2026-11-20 before any API call: the stored clean answers were asked with logprob requests and days
    earlier, so comparing with them would mix drift into the noise effect)."""
    import shutil
    out = os.path.join(D.RENDER, CLEAN)
    os.makedirs(out, exist_ok=True)
    noisy_units = {r["unit"] for r in D.folder_rows(os.path.join(D.RENDER, NAME))}
    with open(os.path.join(out, "meta.jsonl"), "w", encoding="utf-8") as f:
        for r in clean_rows(noisy_units):
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    for suf in ("segs.json", "text_small.json", "text_turbo.json", "sounds.json", "enrol.json", "spk_emb.npy",
                "spk_ids.json"):
        shutil.copyfile(f"data/p1v4/feats/dev_{suf}", f"data/p1v4/feats/{CLEAN}_{suf}")
    print(f"{CLEAN}: {len(clean_rows(noisy_units))} rows; dev front-end files copied")


def api_dir_for(folder):
    def run_dir(system, setting, *a, **kw):
        return os.path.join(OUT, "api" if folder == NAME else "api_clean", system, setting)
    return run_dir


def api(system, key_path, folder=NAME, max_usd=60.0):
    import p1v4_api as API
    patch_folders()
    API.run_dir = api_dir_for(folder)
    API.call = call_no_logprobs
    setting = API_SETTING[system]
    API.run(system, setting, key_path, split=folder, max_usd=max_usd, workers=16)
    API.split_scores(system, setting, folder)


# ------------------------------------------------------------------------------------------------ report

def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def detector(rows, ctx):
    classes = sorted({c for c in D.DET_CLASSES})
    hit, n_real, fa, n_none = ({c: 0 for c in classes} for _ in range(4))
    for r in rows:
        for p in r["points"]:
            t = p["t"]
            real = {c for c, _, _ in D.window_events(r, t)}
            det = {s[0] for s in ctx.point(r, p["k"])[3] if s[3] >= 0.5 and s[2] > t - D.WIN_S and s[1] < t}
            for c in classes:
                if c in real:
                    n_real[c] += 1
                    hit[c] += c in det
                else:
                    n_none[c] += 1
                    fa[c] += c in det
    return {c: {"recall": hit[c] / max(1, n_real[c]), "n_real": n_real[c], "false_alarm": fa[c] / max(1, n_none[c]),
                "n_none": n_none[c]} for c in classes}


def report():
    import p1v4_grounding_report as GR
    patch_folders()
    noisy = D.load_rows(NAME)
    units = {r["unit"] for r in noisy}
    clean = clean_rows(units)
    sg = S.load_groups("dev")
    ctx = {"clean": C.Context("dev"), "noisy": C.Context(NAME)}
    rows = {"clean": clean, "noisy": noisy}
    th = GR.thresholds(D.load_rows("dev"))
    th_ro = {"2b ears": json.load(open("results/main_v04/readout_allclass_dev.json"))["natural"]["all-class ears"]["th"],
             "2c ears": json.load(open("results/main_v04/readout_2c_dev.json"))["natural"]["2c ears"]["th"],
             "2d": json.load(open("results/main_v04/readout_2d_dev.json"))["natural"]["th"]}
    ans = json.load(open("results/main_v04/answer_only_dev.json"))
    dec = {}
    for lab in ("clean", "noisy"):
        sc = json.load(open(f"{OUT}/scores_{lab}.json"))
        d = {"old head": S.decide(keyed(sc["old head"]), *th["old head"])}
        for n, t in th_ro.items():
            d[n] = S.decide(keyed(sc[n]), t["S"], t["R"])
        d["B1-strong"] = keyed(json.load(open(f"{OUT}/b1_{lab}.json")))
        for sys_, name in API_NAME.items():
            ch = ans[name]["chosen"]
            path = os.path.join(OUT, "api_clean", sys_, f"scores_{CLEAN}_{ch['setting']}.json") if lab == "clean" \
                else os.path.join(OUT, "api", sys_, f"scores_{NAME}_{ch['setting']}.json")
            if os.path.exists(path):
                d[name] = S.decide(keyed(json.load(open(path))), ch["th_s"], ch["th_r"])
                if lab == "clean":                  # drift check: re-asked clean decisions vs the stored ones
                    old = S.decide(keyed(json.load(open(ch["path"]))), ch["th_s"], ch["th_r"])
                    ks = [k for k in d[name] if k in old]
                    flips = sum(d[name][k] != old[k] for k in ks)
                    print(f"{name}: re-asked clean decisions differ from the stored ones in {flips}/{len(ks)}")
        dec[lab] = d
    systems = [n for n in dec["clean"] if n in dec["noisy"]]
    cl = GR.cluster_table(D.load_rows("dev"), "dev")
    T = {lab: {n: S.unit_table(rows[lab], dec[lab][n], sg) for n in systems} for lab in rows}
    res = {"render": json.load(open(f"{OUT}/render_info.json")), "systems": systems,
           "detector": {lab: detector(rows[lab], ctx[lab]) for lab in rows}, "parts": {}, "gap_change": {}}
    for part in PARTS:
        us = sorted(u for u, x in T["clean"]["2d"].items() if x["part"] == part and x["subset"] is None)

        def right(lab, n):
            return np.array([T[lab][n][u]["right"] for u in us], float)
        res["parts"][part] = {n: {"clean": float(right("clean", n).mean()), "noisy": float(right("noisy", n).mean())}
                              for n in systems}
        for n in systems:
            if n == "2d":
                continue
            a = (right("noisy", "2d") - right("noisy", n)) - (right("clean", "2d") - right("clean", n))
            c = GR.criterion(us, cl, {}, lambda w, a=a: GR.wmean(w, a), lambda a=a: float(a.mean()))
            res["gap_change"].setdefault(part, {})[f"2d - {n}"] = {
                "clean_gap": float((right("clean", "2d") - right("clean", n)).mean()),
                "noisy_gap": float((right("noisy", "2d") - right("noisy", n)).mean()),
                "change": c["point"], "ci95": c["ci95"]}
    # G5 as registered for the test (amendment 12, added 2026-11-20 after the pilot): the change of the gap between
    # the main system and the label readers, averaged over the readers, then the two parts weighted equally
    readers = [n for n in ("old head", "B1-strong", "B2-fast", "B2-strong") if n in systems]
    us_all, is_r, val = [], [], []
    for part in PARTS:
        us = sorted(u for u, x in T["clean"]["2d"].items() if x["part"] == part and x["subset"] is None)

        def rt(lab, n, us=us):
            return np.array([T[lab][n][u]["right"] for u in us], float)
        a = np.mean([(rt("noisy", "2d") - rt("noisy", n)) - (rt("clean", "2d") - rt("clean", n)) for n in readers], 0)
        us_all += us
        is_r += [part == "r_hear"] * len(us)
        val += list(a)
    val, is_r = np.array(val), np.array(is_r)
    c = GR.criterion(us_all, cl, {}, lambda w: 0.5 * GR.wmean(w[:, is_r], val[is_r]) + 0.5 * GR.wmean(w[:, ~is_r],
                                                                                                    val[~is_r]),
                     lambda: float(0.5 * val[is_r].mean() + 0.5 * val[~is_r].mean()))
    res["G5_dev"] = {"readers": readers, "point": c["point"], "ci95": c["ci95"],
                     "holds (>= +0.05, lower bound > 0)": bool(c["point"] >= 0.05 and c["ci95"][0] > 0)}
    print("G5 (dev pilot):", json.dumps(res["G5_dev"]))
    res["trust"] = {lab: GR.natural_report(GR.natural_points(rows[lab], ctx[lab]), dec[lab])["trust"] for lab in rows}
    json.dump(res, open("results/main_v04/noise_pilot_dev.json", "w"), indent=1, default=str)
    print("render:", json.dumps(res["render"]))
    for c in res["detector"]["clean"]:
        a, b = res["detector"]["clean"][c], res["detector"]["noisy"][c]
        print(f"detector {c:9s} recall {a['recall']:.3f} -> {b['recall']:.3f} (n {a['n_real']}); false alarms "
              f"{a['false_alarm']:.3f} -> {b['false_alarm']:.3f}")
    for part in PARTS:
        for n, x in res["parts"][part].items():
            print(f"{part:7s} {n:10s} clean {x['clean']:.3f} noisy {x['noisy']:.3f} change {x['noisy'] - x['clean']:+.3f}")
        for k, v in res["gap_change"][part].items():
            print(f"{part:7s} gap {k:16s} clean {v['clean_gap']:+.3f} noisy {v['noisy_gap']:+.3f} change "
                  f"{v['change']:+.3f} [{v['ci95'][0]:+.3f}, {v['ci95'][1]:+.3f}]")
    for lab in ("clean", "noisy"):
        for band, row in res["trust"][lab].items():
            print(f"trust {lab} {band}: " + json.dumps({k: (round(v, 3) if isinstance(v, float) else v)
                                                       for k, v in row.items()}))


if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "render":
        render()
    elif cmd == "local":
        local()
    elif cmd == "clean-folder":
        clean_folder()
    elif cmd == "api":
        api(sys.argv[2], sys.argv[3], sys.argv[4] if len(sys.argv) > 4 else NAME)
    elif cmd == "report":
        report()
    else:
        raise SystemExit(__doc__)
